<script setup lang="ts">
import { ref,computed,watch } from 'vue'
import { api,errorText } from '../api'
import {composeDepartmentReport} from '../department-report'
import { actionLabels,listItems,reworkDepartmentOptions } from '../domain'
import type { Row } from '../domain'
const props=defineProps<{modelValue:boolean;action:string;row:Row;resource:string}>();const emit=defineEmits<{ 'update:modelValue':[value:boolean];done:[] }>()
const form=ref<Row>({}),users=ref<Row[]>([]),departments=ref<Row[]>([]),busy=ref(false),error=ref('')
const reportFields=computed<Row[]>(()=>props.action==='progress'?props.row.reportFields??[]:[])
const reportValues=ref<Row>({})
const title=computed(()=>actionLabels[props.action]||props.action)
const reasonRequired=computed(()=>['reject','cancel','deadline','withdraw','extend','transfer','adjust','resolve','unlock','appeals'].includes(props.action)||!!form.value.allowGap||(props.action==='assign'&&props.row.ownerId!=null&&String(form.value.ownerId)!==String(props.row.ownerId)))
watch(()=>props.modelValue,async(open)=>{if(!open)return;reportValues.value={};form.value={reason:'',summary:'',note:'',percent:props.action==='progress'?Number(props.row.percent??0):0,userIds:[],deptIds:[],ownerId:'',userId:'',deadline:'',allowGap:false,score:0,decision:'APPROVED'};error.value='';if(props.action==='reject'&&props.resource==='tasks'){try{const detail=props.row.subTasks?props.row:await api.get('/tasks/'+encodeURIComponent(props.row.id));departments.value=reworkDepartmentOptions(detail)}catch(e){error.value=errorText(e)}}else if(['assign','transfer'].includes(props.action)){try{users.value=listItems(await api.get('/organization/users',{deptId:props.row.deptId}))}catch(e){error.value=errorText(e)}}})
async function submit(){if(busy.value)return;if(reasonRequired.value&&!form.value.reason?.trim()){error.value='请填写操作原因，便于责任追溯';return}if(props.action==='progress'&&reportFields.value.length){for(const field of reportFields.value){if(field.required&&(reportValues.value[field.id]==null||String(reportValues.value[field.id]).trim()==='')){error.value='请填写'+field.name;return}}form.value.note=composeDepartmentReport(reportFields.value,reportValues.value)}if(props.action==='progress'&&String(form.value.note||'').length>4000){error.value='汇报内容合计不能超过4000字，请精简后提交';return}if(props.action==='progress'&&!form.value.note?.trim()){error.value='请填写进展说明';return}if(props.action==='submit'&&!form.value.summary?.trim()){error.value='请填写成果摘要';return}if(['deadline','extend'].includes(props.action)&&!form.value.deadline){error.value='请选择新的截止时间';return}if(props.action==='assign'&&(!form.value.userIds.length||!form.value.userIds.includes(form.value.ownerId))){error.value='请选择执行人员，负责人必须属于执行人员';return}if(props.action==='transfer'&&!form.value.userId){error.value='请选择接收人';return}if(props.action==='reject'&&props.resource==='tasks'&&!form.value.deptIds.length){error.value='请选择需要退回的部门';return}busy.value=true;error.value='';try{const f=form.value;const fields:Record<string,string[]>={'confirm-assign':[],accept:[],receive:[],urge:[],assign:['userIds','ownerId','reason'],progress:['percent','note'],submit:['summary'],withdraw:['reason'],extend:['deadline','reason'],transfer:['userId','reason'],summarize:['allowGap','reason'],reject:['deptIds','reason'],cancel:['reason'],deadline:['deadline','reason'],approve:['reason'],adjust:['score','reason'],resolve:['decision','reason'],unlock:['reason']};const body:Row={version:props.row.version};for(const key of fields[props.action]??['reason'])body[key]=f[key];await api.post(`/${props.resource}/${encodeURIComponent(props.row.id)}/${props.action}`,body);emit('done');emit('update:modelValue',false)}catch(e){error.value=errorText(e)}finally{busy.value=false}}
</script>
<template>
<el-dialog :model-value="modelValue" :title="title" width="560px" class="action-dialog" :close-on-click-modal="false" @update:model-value="emit('update:modelValue',$event)">
<p class="muted">{{ row.title||row.deptName||row.code||'当前记录' }} · 版本 {{ row.version??'—' }}</p><el-alert v-if="error" :title="error" type="error" show-icon :closable="false"/><el-form label-position="top" @submit.prevent="submit">
<el-form-item v-if="['deadline','extend'].includes(action)" label="新截止时间" required><el-date-picker v-model="form.deadline" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" style="width:100%"/></el-form-item>
<template v-if="action==='progress'&&reportFields.length"><el-form-item v-for="field in reportFields" :key="field.id" :label="field.name" :required="field.required"><el-input v-if="field.type==='TEXT'" v-model="reportValues[field.id]" type="textarea" :rows="3" maxlength="4000"/><el-input-number v-else-if="field.type==='NUMBER'" v-model="reportValues[field.id]"/><el-date-picker v-else-if="field.type==='DATE'" v-model="reportValues[field.id]" type="date" value-format="YYYY-MM-DD"/><el-select v-else v-model="reportValues[field.id]"><el-option v-for="option in field.options||[]" :key="option" :value="option" :label="option"/></el-select></el-form-item><p class="muted">至少填写一项，汇报内容合计最多4000字；各部门独立保存记录。</p></template><el-form-item v-else-if="action==='progress'" label="进展说明" required><el-input v-model="form.note" type="textarea" :rows="3"/></el-form-item>
<el-form-item v-if="action==='submit'" label="成果摘要" required><el-input v-model="form.summary" type="textarea" :rows="5" maxlength="5000" show-word-limit/></el-form-item>
<template v-if="action==='assign'"><el-form-item label="执行人员" required><el-select v-model="form.userIds" multiple filterable><el-option v-for="u in users" :key="u.id" :label="u.name" :value="u.id"/></el-select></el-form-item><el-form-item label="主负责人" required><el-select v-model="form.ownerId" filterable><el-option v-for="u in users.filter(u=>form.userIds.includes(u.id))" :key="u.id" :label="u.name" :value="u.id"/></el-select></el-form-item></template>
<el-form-item v-if="action==='transfer'" label="接收人" required><el-select v-model="form.userId" filterable><el-option v-for="u in users" :key="u.id" :label="u.name" :value="u.id"/></el-select></el-form-item>
<el-form-item v-if="action==='reject'&&resource==='tasks'" label="退回部门" required><el-select v-model="form.deptIds" multiple filterable><el-option v-for="d in departments" :key="d.id" :label="d.name" :value="d.id"/></el-select></el-form-item>
<el-form-item v-if="action==='summarize'"><el-checkbox v-model="form.allowGap">申请有缺项汇总（需说明原因）</el-checkbox></el-form-item>
<el-form-item v-if="action==='adjust'" label="调整后分数"><el-input-number v-model="form.score" :min="0" :max="100" :precision="2"/></el-form-item><el-form-item v-if="action==='resolve'" label="处理结论"><el-radio-group v-model="form.decision"><el-radio value="APPROVED">同意申诉</el-radio><el-radio value="REJECTED">驳回申诉</el-radio></el-radio-group></el-form-item>
<el-form-item v-if="reasonRequired||['approve','assign'].includes(action)" label="操作原因 / 审批意见" :required="reasonRequired"><el-input v-model="form.reason" type="textarea" :rows="4" maxlength="2000" show-word-limit/></el-form-item>
<p v-if="['accept','cancel','unlock','confirm-assign'].includes(action)" class="notice">请核对当前记录。提交后由服务端检查权限、状态及版本，并保留操作记录。</p>
</el-form><template #footer><el-button :disabled="busy" @click="emit('update:modelValue',false)">返回</el-button><el-button type="primary" :loading="busy" @click="submit">确认{{ title }}</el-button></template>
</el-dialog>
</template>
